import { test, expect } from "@playwright/test";

// Data-driven: bảng phân vùng và giá trị biên cho ô mật khẩu
const cases = [
  { name: "7 ký tự (dưới biên)", password: "Abc1234", error: "Mật khẩu tối thiểu 8 ký tự" },
  { name: "8 ký tự (đúng biên)", password: "Abc12345", error: null },
  { name: "không có chữ số", password: "Abcdefgh", error: "Mật khẩu cần ít nhất 1 chữ số" },
];

for (const c of cases) {
  test(`mật khẩu: ${c.name}`, async ({ page }) => {
    await page.goto("/register");
    await page.getByLabel("Mật khẩu").fill(c.password);
    await page.getByLabel("Mật khẩu").blur();
    const error = page.getByTestId("password-error");
    if (c.error) await expect(error).toHaveText(c.error);
    else await expect(error).toBeHidden();
  });
}

